import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0091: Shared Diagnostics Crate (plugin-ext-diag)","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0091-plugin-ext-diag.md","filePath":"vendored/handl/project/adrs/0091-plugin-ext-diag.md"}`),a={name:`handl/project/adrs/0091-plugin-ext-diag.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0091-shared-diagnostics-crate-plugin-ext-diag" tabindex="-1">ADR-0091: Shared Diagnostics Crate (<code>plugin-ext-diag</code>) <a class="header-anchor" href="#adr-0091-shared-diagnostics-crate-plugin-ext-diag" aria-label="Permalink to “ADR-0091: Shared Diagnostics Crate (plugin-ext-diag)”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Implemented (merged to main). Part of the bootstrap tooling strategy (<a href="./0085-bootstrap-tooling-strategy.html">ADR-0085</a>).</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Diagnostics-adjacent code — <code>Diagnostic</code> shapes, spans, severities, fixes, rendering to <code>file:line:col</code> output — is currently scattered: the expression-level diagnostics live in <code>plugin-diag-expression</code>, while fmt, lint, typecheck, the LSP features, and the CLI each carry their own partial variants. Every new tool either forks a diagnostics type or reaches into another crate&#39;s internals. The tools in ADR-0086..0090 all need the same type family, and the CLI (ADR-0090) needs one renderer for all of them.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Create <code>crates/plugin-ext-diag</code> as the single home for diagnostics infrastructure, and move/consolidate existing diagnostic code into it:</p><ul><li><strong>Types:</strong> <code>Diagnostic { rule, severity, span, message, fix? }</code>, <code>Severity { Error, Warning, Info }</code>, <code>Span</code> (byte range + line/col), <code>Fix</code> (text edit). Owned here; every other crate depends on these.</li><li><strong>Rendering:</strong> one shared renderer (human <code>file:line:col: severity [rule]: message</code>, plus <code>--json</code>), used by <code>host-cli</code>, the test runner, and the LSP adapter — one output format across all tools.</li><li><strong>Fix application:</strong> span-ordered, idempotent text-edit application with the re-parse fixpoint policy from ADR-0087, shared by lint and fmt.</li><li><strong>Relationship to <code>plugin-diag-expression</code>:</strong> it keeps its expression-specific rules/production logic but switches to the shared <code>Diagnostic</code>/<code>Span</code> types from <code>plugin-ext-diag</code> (a dependency, not a consolidation of its rule logic).</li><li><strong>Generic, not surface-coupled:</strong> the crate knows spans and text, not the v0.1 grammar — it serves every handl language.</li></ul><p>Migration: introduce the crate with the types above → switch <code>plugin-ext-fmt</code>, <code>plugin-ext-lint</code>, <code>plugin-engine-typecheck</code>, and <code>plugin-lib-test</code> to the shared types (deprecating their local variants in the same PR that stops using them) → switch <code>host-cli</code> rendering to the shared renderer.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>All tools print diagnostics identically; CI and editor consumers get one stable format.</li><li>Cross-tool features become trivial: lint&#39;s <code>fmt</code> rule, LSP publishing lint/typecheck diagnostics, <code>hnl check</code> aggregating all sources.</li><li>One more crate in the dependency graph, but it sits at the bottom of the tooling stack (depends only on <code>platform</code> contracts) and has no plugin logic of its own.</li></ul><h2 id="status-1" tabindex="-1">Status <a class="header-anchor" href="#status-1" aria-label="Permalink to “Status”">​</a></h2><p>Implemented (merged to main).</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};